class KernelBuilder:
    def __init__(self):
        self.instrs = []
        self.scratch = {}
        self.scratch_debug = {}
        self.scratch_ptr = 0
        self.const_map = {}

    def debug_info(self):
        return DebugInfo(scratch_map=self.scratch_debug)

    def build(self, slots: list[tuple[Engine, tuple]], vliw: bool = False):
        """Pack dependency-independent operations into legal VLIW bundles.

        Each bundle represents one cycle.  The scheduler uses a conservative
        scratch-register scoreboard: a slot cannot share a bundle with another
        slot when it reads a value written by that slot, writes a value read by
        that slot, or writes the same location.  Independent batch lanes can
        therefore fill the available ALU, load, store, and flow capacity.
        """
        limits = {
            "alu": 12,
            "valu": 6,
            "load": 2,
            "store": 2,
            "flow": 1,
            "debug": 64,
        }

        def rw(engine, op):
            if engine == "debug":
                return set(), set()

            if engine == "alu":
                return {op[1]}, {op[2], op[3]}

            if engine == "valu":
                if op[0] == "vbroadcast":
                    return set(range(op[1], op[1] + VLEN)), {op[2]}
                if op[0] == "multiply_add":
                    reads = set(range(op[2], op[2] + VLEN))
                    reads |= set(range(op[3], op[3] + VLEN))
                    reads |= set(range(op[4], op[4] + VLEN))
                    return set(range(op[1], op[1] + VLEN)), reads
                writes = set(range(op[1], op[1] + VLEN))
                reads = set(range(op[2], op[2] + VLEN))
                reads |= set(range(op[3], op[3] + VLEN))
                return writes, reads

            if engine == "load":
                if op[0] == "const":
                    return {op[1]}, set()
                if op[0] == "load_offset":
                    return {op[1] + op[3]}, {op[2]}
                if op[0] == "vload":
                    return set(range(op[1], op[1] + VLEN)), {op[2]}
                return {op[1]}, {op[2]}

            if engine == "store":
                if op[0] == "vstore":
                    return set(), {op[1], *range(op[2], op[2] + VLEN)}
                return set(), {op[1], op[2]}

            if engine == "flow":
                if op[0] == "select":
                    return {op[1]}, {op[2], op[3], op[4]}
                if op[0] == "vselect":
                    writes = set(range(op[1], op[1] + VLEN))
                    reads = set(range(op[2], op[2] + VLEN))
                    reads |= set(range(op[3], op[3] + VLEN))
                    reads |= set(range(op[4], op[4] + VLEN))
                    return writes, reads
                if op[0] == "add_imm":
                    return {op[1]}, {op[2]}
                if op[0] in ("cond_jump", "cond_jump_rel"):
                    return set(), {op[1]}
                if op[0] == "jump_indirect":
                    return set(), {op[1]}
                if op[0] == "trace_write":
                    return set(), {op[1]}
                return set(), set()

            return set(), set()

        pending = list(slots)
        result = []

        while pending:
            # Debug comparisons must observe committed writes.  Treat the
            # first debug slot as a zero-cycle ordering barrier and never pack
            # operations from after it into the preceding bundle.
            if pending[0][0] == "debug":
                result.append({"debug": [pending.pop(0)[1]]})
                continue

            bundle = {}
            reads = set()
            writes = set()
            chosen = []

            for index, (engine, op) in enumerate(pending):
                if engine == "debug":
                    break
                if len(bundle.get(engine, [])) >= limits[engine]:
                    continue

                slot_writes, slot_reads = rw(engine, op)
                if slot_writes & (reads | writes):
                    continue
                if slot_reads & writes:
                    continue

                bundle.setdefault(engine, []).append(op)
                reads |= slot_reads
                writes |= slot_writes
                chosen.append(index)

            if not chosen:
                raise AssertionError("VLIW scheduler made no progress")

            for index in reversed(chosen):
                pending.pop(index)
            result.append(bundle)

        return result

    def add(self, engine, slot):
        self.instrs.append({engine: [slot]})

    def alloc_scratch(self, name=None, length=1):
        addr = self.scratch_ptr
        if name is not None:
            self.scratch[name] = addr
            self.scratch_debug[addr] = (name, length)
        self.scratch_ptr += length
        assert self.scratch_ptr <= SCRATCH_SIZE, "Out of scratch space"
        return addr

    def scratch_const(self, val, name=None):
        if val not in self.const_map:
            addr = self.alloc_scratch(name)
            self.add("load", ("const", addr, val))
            self.const_map[val] = addr
        return self.const_map[val]

    def build_hash(self, val_hash_addr, tmp1, tmp2, round, i):
        slots = []
        for hi, (op1, val1, op2, op3, val3) in enumerate(HASH_STAGES):
            slots.append(("alu", (op1, tmp1, val_hash_addr, self.scratch_const(val1))))
            slots.append(("alu", (op3, tmp2, val_hash_addr, self.scratch_const(val3))))
            slots.append(("alu", (op2, val_hash_addr, tmp1, tmp2)))
            slots.append(("debug", ("compare", val_hash_addr, (round, i, "hash_stage", hi))))
        return slots

    def build_kernel(self, forest_height: int, n_nodes: int, batch_size: int, rounds: int):
        tmp1 = self.alloc_scratch("tmp1")
        tmp2 = self.alloc_scratch("tmp2")
        tmp3 = self.alloc_scratch("tmp3")

        init_vars = [
            "rounds",
            "n_nodes",
            "batch_size",
            "forest_height",
            "forest_values_p",
            "inp_indices_p",
            "inp_values_p",
        ]
        for name in init_vars:
            self.alloc_scratch(name)

        for i, name in enumerate(init_vars):
            self.add("load", ("const", tmp1, i))
            self.add("load", ("load", self.scratch[name], tmp1))

        zero_const = self.scratch_const(0)
        one_const = self.scratch_const(1)
        two_const = self.scratch_const(2)

        self.add("flow", ("pause",))
        self.add("debug", ("comment", "Starting loop"))

        body = []

        # Six scalar scratch words per batch lane are sufficient:
        # idx, val, node/address, and two hash temporaries.  The node word is
        # reused as the branch increment after the gather is consumed.
        for round_index in range(rounds):
            for batch_index in range(batch_size):
                idx = self.alloc_scratch()
                val = self.alloc_scratch()
                node_or_addr = self.alloc_scratch()
                addr = self.alloc_scratch()
                hash_tmp1 = self.alloc_scratch()
                hash_tmp2 = self.alloc_scratch()

                body.append(("flow", ("add_imm", addr, self.scratch["inp_indices_p"], batch_index)))
                body.append(("load", ("load", idx, addr)))
                body.append(("debug", ("compare", idx, (round_index, batch_index, "idx"))))

                body.append(("flow", ("add_imm", addr, self.scratch["inp_values_p"], batch_index)))
                body.append(("load", ("load", val, addr)))
                body.append(("debug", ("compare", val, (round_index, batch_index, "val"))))

                body.append(("alu", ("+", addr, self.scratch["forest_values_p"], idx)))
                body.append(("load", ("load", node_or_addr, addr)))
                body.append(("debug", ("compare", node_or_addr, (round_index, batch_index, "node_val"))))

                body.append(("alu", ("^", val, val, node_or_addr)))

                for hash_stage, (op1, value1, op2, op3, value3) in enumerate(HASH_STAGES):
                    body.append(("alu", (op1, hash_tmp1, val, self.scratch_const(value1))))
                    body.append(("alu", (op3, hash_tmp2, val, self.scratch_const(value3))))
                    body.append(("alu", (op2, val, hash_tmp1, hash_tmp2)))
                    body.append(("debug", ("compare", val, (round_index, batch_index, "hash_stage", hash_stage))))

                body.append(("debug", ("compare", val, (round_index, batch_index, "hashed_val"))))

                body.append(("alu", ("%", hash_tmp1, val, two_const)))
                body.append(("alu", ("==", hash_tmp1, hash_tmp1, zero_const)))
                body.append(("flow", ("select", node_or_addr, hash_tmp1, one_const, two_const)))
                body.append(("alu", ("*", idx, idx, two_const)))
                body.append(("alu", ("+", idx, idx, node_or_addr)))
                body.append(("debug", ("compare", idx, (round_index, batch_index, "next_idx"))))

                body.append(("alu", ("<", hash_tmp1, idx, self.scratch["n_nodes"])))
                body.append(("flow", ("select", idx, hash_tmp1, idx, zero_const)))
                body.append(("debug", ("compare", idx, (round_index, batch_index, "wrapped_idx"))))

                body.append(("flow", ("add_imm", addr, self.scratch["inp_indices_p"], batch_index)))
                body.append(("store", ("store", addr, idx)))
                body.append(("flow", ("add_imm", addr, self.scratch["inp_values_p"], batch_index)))
                body.append(("store", ("store", addr, val)))

        self.instrs.extend(self.build(body, vliw=True))
        self.instrs.append({"flow": [("pause",)]})

from problem import HASH_STAGES, SCRATCH_SIZE, VLEN


class KernelBuilder:
    def __init__(self):
        self.instrs = []
        self.scratch = {}
        self.scratch_debug = {}
        self.scratch_ptr = 0
        self.const_map = {}
        self._vector_const_map = {}

    def debug_info(self):
        from problem import DebugInfo
        return DebugInfo(scratch_map=self.scratch_debug)

    @staticmethod
    def _slot_accesses(engine, slot):
        """Return (read addresses, written addresses) for dependency-aware packing."""
        reads = set()
        writes = set()

        def add_range(base, length=1, target=None):
            collection = writes if target == "write" else reads
            collection.update(range(base, base + length))

        if engine == "alu":
            _, dest, a1, a2 = slot
            add_range(a1)
            add_range(a2)
            add_range(dest, target="write")
        elif engine == "valu":
            if slot[0] == "vbroadcast":
                _, dest, src = slot
                add_range(src)
                add_range(dest, VLEN, target="write")
            elif slot[0] == "multiply_add":
                _, dest, a, b, c = slot
                add_range(a, VLEN)
                add_range(b, VLEN)
                add_range(c, VLEN)
                add_range(dest, VLEN, target="write")
            else:
                _, dest, a1, a2 = slot
                add_range(a1, VLEN)
                add_range(a2, VLEN)
                add_range(dest, VLEN, target="write")
        elif engine == "load":
            op = slot[0]
            if op == "const":
                _, dest, _ = slot
                add_range(dest, target="write")
            elif op == "load":
                _, dest, addr = slot
                add_range(addr)
                add_range(dest, target="write")
            elif op == "load_offset":
                _, dest, addr, offset = slot
                add_range(addr + offset)
                add_range(dest + offset, target="write")
            elif op == "vload":
                _, dest, addr = slot
                add_range(addr)
                add_range(dest, VLEN, target="write")
        elif engine == "store":
            _, addr, src = slot
            add_range(addr)
            if slot[0] == "vstore":
                add_range(src, VLEN)
            else:
                add_range(src)
        elif engine == "flow":
            op = slot[0]
            if op == "select":
                _, dest, cond, a, b = slot
                add_range(cond)
                add_range(a)
                add_range(b)
                add_range(dest, target="write")
            elif op == "vselect":
                _, dest, cond, a, b = slot
                add_range(cond, VLEN)
                add_range(a, VLEN)
                add_range(b, VLEN)
                add_range(dest, VLEN, target="write")
            elif op == "add_imm":
                _, dest, src, _ = slot
                add_range(src)
                add_range(dest, target="write")
            elif op in ("cond_jump", "cond_jump_rel"):
                add_range(slot[1])
            elif op in ("trace_write", "jump_indirect", "coreid"):
                if op != "coreid":
                    add_range(slot[1])
                else:
                    add_range(slot[1], target="write")
            elif op not in ("pause", "halt", "jump"):
                for value in slot[1:]:
                    if isinstance(value, int):
                        add_range(value)
        elif engine == "debug":
            if slot[0] in ("compare", "vcompare"):
                add_range(slot[1], VLEN if slot[0] == "vcompare" else 1)

        return reads, writes

    def build(self, slots, vliw=False):
        """Pack a topologically ordered slot stream into legal VLIW bundles.

        The scheduler never reorders slots. It only places a slot in the current
        bundle when engine capacity and scratch read/write dependencies permit it.
        This preserves the simulator's end-of-cycle write semantics while allowing
        independent lanes and engines to issue together.
        """
        if not vliw:
            return [{engine: [slot]} for engine, slot in slots]

        bundles = []
        current = {}
        current_reads = set()
        current_writes = set()

        def flush():
            nonlocal current, current_reads, current_writes
            if current:
                bundles.append(current)
            current = {}
            current_reads = set()
            current_writes = set()

        for engine, slot in slots:
            if engine == "debug":
                flush()
                bundles.append({"debug": [slot]})
                continue

            reads, writes = self._slot_accesses(engine, slot)
            limit = {"alu": 12, "valu": 6, "load": 2, "store": 2, "flow": 1}.get(engine, 64)
            engine_full = len(current.get(engine, [])) >= limit
            hazard = bool(reads & current_writes) or bool(writes & current_reads) or bool(writes & current_writes)

            if engine_full or hazard:
                flush()

            current.setdefault(engine, []).append(slot)
            current_reads.update(reads)
            current_writes.update(writes)

        flush()
        return bundles

    def add(self, engine, slot):
        self.instrs.append({engine: [slot]})

    def alloc_scratch(self, name=None, length=1):
        addr = self.scratch_ptr
        if name is not None:
            self.scratch[name] = addr
            self.scratch_debug[addr] = (name, length)
        self.scratch_ptr += length
        assert self.scratch_ptr <= SCRATCH_SIZE, "Out of scratch space"
        return addr

    def scratch_const(self, val, name=None):
        if val not in self.const_map:
            addr = self.alloc_scratch(name)
            self.add("load", ("const", addr, val))
            self.const_map[val] = addr
        return self.const_map[val]

    def vector_const(self, val):
        if val not in self._vector_const_map:
            scalar = self.scratch_const(val)
            addr = self.alloc_scratch(length=VLEN)
            self.add("valu", ("vbroadcast", addr, scalar))
            self._vector_const_map[val] = addr
        return self._vector_const_map[val]

    def build_hash(self, val_hash_addr, tmp1, tmp2, round, i):
        slots = []
        for hi, (op1, val1, op2, op3, val3) in enumerate(HASH_STAGES):
            slots.append(("alu", (op1, tmp1, val_hash_addr, self.scratch_const(val1))))
            slots.append(("alu", (op3, tmp2, val_hash_addr, self.scratch_const(val3))))
            slots.append(("alu", (op2, val_hash_addr, tmp1, tmp2)))
            slots.append(("debug", ("compare", val_hash_addr, (round, i, "hash_stage", hi))))
        return slots

    def build_kernel(self, forest_height: int, n_nodes: int, batch_size: int, rounds: int):
        tmp = self.alloc_scratch("tmp")
        init_vars = [
            "rounds", "n_nodes", "batch_size", "forest_height",
            "forest_values_p", "inp_indices_p", "inp_values_p",
        ]
        for name in init_vars:
            self.alloc_scratch(name)

        init_slots = []
        for i, name in enumerate(init_vars):
            init_slots.append(("load", ("const", tmp, i)))
            init_slots.append(("load", ("load", self.scratch[name], tmp)))
        self.instrs.extend(self.build(init_slots, vliw=True))

        one = self.scratch_const(1)
        two = self.scratch_const(2)
        batch_const = self.scratch_const(batch_size)
        zero_vec = self.vector_const(0)
        one_vec = self.vector_const(1)
        two_vec = self.vector_const(2)
        hash_vec_consts = {
            value: self.vector_const(value)
            for stage in HASH_STAGES
            for value in (stage[1], stage[4])
        }

        self.instrs.append({"flow": [("pause",)]})
        self.instrs.append({"debug": [("comment", "Starting loop")]})

        groups = []
        for start in range(0, batch_size, VLEN):
            idx = self.alloc_scratch(length=VLEN)
            val = self.alloc_scratch(length=VLEN)
            gather = self.alloc_scratch(length=VLEN)
            htmp = self.alloc_scratch(length=VLEN)
            idx_addr = self.alloc_scratch()
            val_addr = self.alloc_scratch()
            groups.append((start, idx, val, gather, htmp, idx_addr, val_addr))

        for round_index in range(rounds):
            body = []
            for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                body.append(("flow", ("add_imm", idx_addr, self.scratch["inp_indices_p"], start)))
            for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                body.append(("alu", ("+", val_addr, idx_addr, batch_const)))
            for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                body.append(("load", ("vload", idx, idx_addr)))
                body.append(("load", ("vload", val, val_addr)))
            for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                for lane in range(VLEN):
                    body.append(("alu", ("+", gather + lane, self.scratch["forest_values_p"], idx + lane)))
            for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                for lane in range(VLEN):
                    body.append(("load", ("load", gather + lane, gather + lane)))
            for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                body.append(("valu", ("^", val, val, gather)))
            for op1, value1, op2, op3, value3 in HASH_STAGES:
                for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                    body.append(("valu", (op1, htmp, val, hash_vec_consts[value1])))
                    body.append(("valu", (op3, gather, val, hash_vec_consts[value3])))
                for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                    body.append(("valu", (op2, val, htmp, gather)))
            for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                body.append(("valu", ("%", htmp, val, two_vec)))
            for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                body.append(("valu", ("==", htmp, htmp, zero_vec)))
            for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                body.append(("flow", ("vselect", gather, htmp, one_vec, two_vec)))
                body.append(("valu", ("*", idx, idx, two_vec)))
            for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                body.append(("valu", ("+", idx, idx, gather)))
            n_nodes_vec = self.vector_const(n_nodes)
            for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                body.append(("valu", ("<", htmp, idx, n_nodes_vec)))
            for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                body.append(("flow", ("vselect", idx, htmp, idx, zero_vec)))
            for start, idx, val, gather, htmp, idx_addr, val_addr in groups:
                body.append(("store", ("vstore", idx_addr, idx)))
                body.append(("store", ("vstore", val_addr, val)))

            self.instrs.extend(self.build(body, vliw=True))
            self.instrs.append({"flow": [("pause",)]})
